  "body": "<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Ultimate Job Aggregator</title>
    <link href="https://stackpath.bootstrapcdn.com/bootstrap/4.5.2/css/bootstrap.min.css" rel="stylesheet">
</head>
<body>
    <div class="container mt-5">
        <h1 class="text-center">Ultimate Job Aggregator</h1>
        <div class="row justify-content-center mt-4">
            <div class="col-md-6">
                <form id="filter-form">
                    <div class="form-group">
                        <label for="job-type">Filter by Job Type</label>
                        <select id="job-type" class="form-control">
                            <option value="">All</option>
                            <option value="back-end">back-end</option>
                            <option value="front-end">front-end</option>
                            <option value="private">private</option>
                        </select>
                    </div>
                    <button type="submit" class="btn btn-primary btn-block">Filter Jobs</button>
                </form>
                <div class="mt-4" id="result"></div>
            </div>
        </div>
    </div>

    <script>
        document.getElementById('filter-form').addEventListener('submit', async function(event) {
            event.preventDefault();
            const jobType = document.getElementById('job-type').value;
            const resultDiv = document.getElementById('result');
            resultDiv.innerHTML = '';

            try {
                const response = await fetch('/jobs', {
                    method: 'POST',
                    headers: {
                        'Content-Type': 'application/json'
                    },
                    body: JSON.stringify({ job_type: jobType })
                });
                if (response.ok) {
                    const data = await response.json();
                    if (data.length === 0) {
                        resultDiv.innerHTML = '<div class="alert alert-warning" role="alert">No jobs found</div>';
                    } else {
                        let jobsTable = `
                            <table class="table table-bordered mt-4">
                                <thead>
                                    <tr>
                                        <th>ID</th>
                                        <th>Name</th>
                                        <th>Type</th>
                                        <th>Description</th>
                                    </tr>
                                </thead>
                                <tbody>
                        `;
                        data.forEach(user => {
                            jobsTable += `
                                <tr>
                                    <td>${user.id}</td>
                                    <td>${user.name}</td>
                                    <td>${user.type}</td>
                                    <td>${user.description}</td>
                                </tr>
                            `;
                        });
                        jobsTable += '</tbody></table>';
                        resultDiv.innerHTML = jobsTable;
                    }
                } else {
                    const errorData = await response.json();
                    resultDiv.innerHTML = `
                        <div class="alert alert-danger" role="alert">
                            Error: ${errorData.detail}
                        </div>
                    `;
                }
            } catch (error) {
                resultDiv.innerHTML = `
                    <div class="alert alert-danger" role="alert">
                        Network error or server is down.
                    </div>
                `;
            }
        });
    </script>
</body>
</html>
",
  "burp": "not routed through Burp"
}

